import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';
import ProgressBar from '../components/ProgressBar';

export default function RoadmapPage() {
  const { name } = useParams();
  const navigate = useNavigate();
  const [roadmapPlan, setRoadmapPlan] = useState([]);
  const [domain, setDomain] = useState('');
  const [timeline, setTimeline] = useState('');

  useEffect(() => {
    const rawPlan = localStorage.getItem('roadmapPlan');
    const selectedDomain = localStorage.getItem('selectedDomain') || name || 'web-development';
    const savedTimeline = localStorage.getItem('timeline') || '3 months';

    if (rawPlan) {
      try {
        const parsedPlan = JSON.parse(rawPlan);
        // Only set the state if we actually have an array
        if (Array.isArray(parsedPlan)) {
          setRoadmapPlan(parsedPlan);
        }
      } catch (e) {
        console.error("Local storage parsing error", e);
      }
    }
    setDomain(selectedDomain);
    setTimeline(savedTimeline);
  }, [name]);

  const handleStartLearning = () => navigate('/tasks');

  const getDomainTitle = () => domain.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

  const completedDays = JSON.parse(localStorage.getItem("completedDays") || "[]");
  
  // 🔥 FIX: Check if roadmapPlan is an array before calling .flat()
  const totalTasks = Array.isArray(roadmapPlan) ? roadmapPlan.flat().length : 0;
  const totalDays = Math.ceil(totalTasks / 4);
  const completedCount = completedDays.length;
  const remainingDays = Math.max(totalDays - completedCount, 0);

  const completionPercentage = totalDays > 0 ? Math.min(100, Math.round((completedCount / totalDays) * 100)) : 0;

  const getPhaseProgress = (phaseIndex, phaseTasks) => {
    const tasksPerDay = 4;
    let tasksBefore = 0;
    for (let i = 0; i < phaseIndex; i++) {
        if (roadmapPlan[i]) tasksBefore += roadmapPlan[i].length;
    }

    const phaseStartDay = Math.floor(tasksBefore / tasksPerDay) + 1;
    const phaseTotalDays = Math.ceil(phaseTasks.length / tasksPerDay);
    let completedInPhase = completedDays.filter(day => day >= phaseStartDay && day < phaseStartDay + phaseTotalDays).length;

    return Math.min(100, Math.round((completedInPhase / phaseTotalDays) * 100));
  };

  const getCurrentPhaseIndex = () => {
    const tasksPerDay = 4;
    let tasksCovered = completedDays.length * tasksPerDay;
    let cumulativeTasks = 0;
    for (let i = 0; i < roadmapPlan.length; i++) {
      cumulativeTasks += roadmapPlan[i].length;
      if (tasksCovered < cumulativeTasks) return i;
    }
    return Math.max(0, roadmapPlan.length - 1);
  };

  const currentPhaseIndex = getCurrentPhaseIndex();

  const isPhaseCompleted = (phaseIndex, phaseTasks) => {
    return getPhaseProgress(phaseIndex, phaseTasks) === 100;
  };

  return (
    <div className="space-y-8 pb-20">
      <div className="rounded-[2rem] border border-slate-300 bg-gradient-to-br from-white to-blue-50 p-8 shadow-lg dark:border-slate-700 dark:from-slate-800 dark:to-slate-900">
        <h1 className="text-4xl font-bold text-slate-900 dark:text-white uppercase tracking-tight">{getDomainTitle()} Roadmap</h1>
        <p className="mt-2 text-slate-600 dark:text-slate-400 font-medium">Concept-Driven Syllabus for {timeline}</p>
        
        <div className="mt-8 flex flex-col gap-6 lg:flex-row">
          <div className="flex-1 bg-white/50 p-6 rounded-3xl border border-white/50 backdrop-blur-md">
            <p className="text-sm font-bold text-slate-500 uppercase mb-2">Curriculum Completion</p>
            <ProgressBar label="Overall" value={completionPercentage} />
          </div>
          <div className="bg-teal-100 p-6 rounded-3xl border border-teal-200 flex items-center justify-center min-w-[200px] dark:bg-slate-700">
            <div className="text-center">
              <p className="text-xs font-bold text-teal-600 uppercase">Duration</p>
              <p className="text-2xl font-black text-teal-900 dark:text-teal-200">{timeline}</p>
            </div>
          </div>
          <div className="bg-orange-100 p-6 rounded-3xl border border-orange-200 flex items-center justify-center min-w-[200px] dark:bg-slate-700">
            <div className="text-center">
              <p className="text-xs font-bold text-orange-600 uppercase">Remaining</p>
              <p className="text-2xl font-black text-orange-900 dark:text-orange-200">{remainingDays} / {totalDays} d</p>
            </div>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        <h2 className="text-2xl font-bold flex items-center gap-3">📚 Learning Phases <span className="text-sm font-normal text-slate-500">({roadmapPlan.length} weeks)</span></h2>
        
        {roadmapPlan.length === 0 ? (
            <div className="text-center py-10 text-slate-500 bg-white rounded-3xl border">No curriculum generated. Complete the assessment to build your path!</div>
        ) : (
            roadmapPlan.map((phase, idx) => (
                <div key={idx} className={`bg-white rounded-[2rem] border p-8 shadow-sm transition-all ${isPhaseCompleted(idx, phase) ? 'bg-green-50 border-green-200' : idx === currentPhaseIndex ? 'border-teal-400 bg-blue-50/30' : 'border-slate-200'}`}>
                  <div className="flex items-start justify-between mb-6">
                    <div className="flex items-center gap-4">
                      <span className="h-12 w-12 rounded-2xl bg-teal-500 flex items-center justify-center text-white text-xl font-bold shadow-lg shadow-teal-200">{idx + 1}</span>
                      <div>
                        <h3 className="text-xl font-bold">Phase {idx + 1}: {idx === currentPhaseIndex && '📍 Current'}</h3>
                        <p className="text-sm text-slate-500">{phase.length} curated technical tasks</p>
                      </div>
                    </div>
                    <div className="w-48 text-right">
                      <p className="text-xs font-bold text-slate-400 mb-1 uppercase">Phase Progress</p>
                      <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
                          <div className="h-full bg-teal-500" style={{width: `${getPhaseProgress(idx, phase)}%`}}></div>
                      </div>
                    </div>
                  </div>
      
                  <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                    {phase.slice(0, 4).map((task, tIdx) => (
                      <div key={tIdx} className="p-4 rounded-2xl bg-white border border-slate-100 text-sm text-slate-700 flex gap-3 items-start shadow-sm">
                        <span className="text-teal-500 font-bold">✓</span>
                        {task}
                      </div>
                    ))}
                  </div>
                  {phase.length > 4 && <p className="mt-4 text-xs text-slate-400 italic font-medium">+ {phase.length - 4} more technical tasks in this phase</p>}
                </div>
              ))
        )}
      </div>

      <div className="flex justify-center">
        <Button onClick={handleStartLearning} className="px-12 py-5 text-xl shadow-xl rounded-full hover:scale-105 transition-transform">Start Learning Journey 🚀</Button>
      </div>
    </div>
  );
}
